const fs = require('fs');
const db = require('./database');

function processData(inputFile, callback) {
  fs.readFile(inputFile, 'utf8', (err, data) => {
    if (err) return callback(err);

    db.connect((err, connection) => {
      if (err) return callback(err);

      connection.query('SELECT * FROM items WHERE type = ?', [data.trim()], (err, results) => {
        if (err) {
          connection.release();
          return callback(err);
        }

        fs.writeFile('output.json', JSON.stringify(results), (err) => {
          connection.release();
          if (err) return callback(err);
          callback(null, 'Processing complete');
        });
      });
    });
  });
}

