{"filepath": "in_memory_cache.py", "content": "from cache_interface import Cache
import time

class InMemoryCache(Cache):
    def __init__(self):
        super().__init__()
        self.data = {}
        self.expirations = {}

    def set(self, key, value, ttl=None):
        with self.lock:
            self.data[key] = value
            if ttl:
                self.expirations[key] = time.time() + ttl

    def get(self, key):
        with self.lock:
            if key in self.expirations and time.time() > self.expirations[key]:
                del self.data[key]
                del self.expirations[key]
                return None
            return self.data.get(key)

    def delete(self, key):
        with self.lock:
            self.data.pop(key, None)
            self.expirations.pop(key, None)
"}

