from sqlite_cache import SQLiteCache

class TestCacheImplementations(unittest.TestCase):
    def setUp(self):
        self.caches = [
            InMemoryCache(),
            SQLiteCache(':memory:')  # In-memory SQLite
        ]

    def test_set_get(self):
        for cache in self.caches:
            with self.subTest(cache=cache.__class__.__name__):
                cache.set('foo', 'bar')
                self.assertEqual(cache.get('foo'), 'bar')

    def test_ttl_expiration(self):
        for cache in self.caches:
            with self.subTest(cache=cache.__class__.__name__):
                cache.set('temp', 'value', ttl=0.1)  # 100ms TTL
                time.sleep(0.15)
                self.assertIsNone(cache.get('temp'))

    def test_delete(self):
        for cache in self.caches:
            with self.subTest(cache=cache.__class__.__name__):
                cache.set('to_delete', 'data')
                cache.delete('to_delete')
                self.assertIsNone(cache.get('to_delete'))

    def test_thread_safety(self):
        import threading
        for cache in self.caches:
            with self.subTest(cache=cache.__class__.__name__):
                # Test that concurrent access doesn't corrupt data
                cache.set('counter', 0)
                threads = []
                def increment():
                    for _ in range(100):
                        val = cache.get('counter')
                        cache.set('counter', val + 1)

                for _ in range(10):
                    t = threading.Thread(target=increment)
                    threads.append(t)
                    t.start()

                for t in threads:
                    t.join()

                self.assertEqual(cache.get('counter'), 1000)

if __name__ == '__main__':
    unittest.main()"}

